from pathlib import Path
import subprocess,os,json,time,hashlib
root=Path('/srv/projects/telegram-robot-leads')
old_state=Path('/var/lib/telegram-robot-leads')
old_private=Path('/root/project-secrets/telegram-robot-leads')
new_state=root/'data'
new_private=root/'private'
recovery=root/'.pm2-state-vault-rollback.config.cjs'
paths=[
 'ecosystem.config.js','scripts/public_group_discovery.py','scripts/lead_health.py',
 'scripts/safe_runtime.py','scripts/member_groups.py','scripts/telethon_sessions.py',
 'scripts/telegram-robot-leads-status.sh','scripts/deploy_project_only.py',
 'tests/test_safe_growth.py'
]
def cmd(args,t=35):
 return subprocess.run(args,capture_output=True,text=True,timeout=t)
def pm():
 q=cmd(['pm2','jlist'],16)
 if q.returncode:raise RuntimeError('Cannot read PM2')
 return [x for x in json.loads(q.stdout) if x.get('name') in ('telegram-robot-leads','iptvpn_bot')]
def details(records,name):
 x=[a for a in records if a.get('name')==name]
 if len(x)!=1:raise RuntimeError('Unexpected process count for '+name)
 e=x[0].get('pm2_env') or {}
 return {'status':e.get('status'),'pid':x[0].get('pid'),'cwd':e.get('pm_cwd'),'script':e.get('pm_exec_path'),'args':e.get('args'),'state':e.get('TELEGRAM_OPERATION_STATE'),'journal':e.get('TELEGRAM_EVENT_JOURNAL')}
def hashes(vault):
 return {p.name:(p.stat().st_ino,p.stat().st_size,hashlib.sha256(p.read_bytes()).digest()) for p in vault.glob('*.session')}
if not root.is_dir() or root.is_symlink():raise RuntimeError('Canonical root missing')
if not old_state.is_dir() or old_state.is_symlink() or not old_private.is_dir() or old_private.is_symlink():raise RuntimeError('Actual state/vault directories invalid')
if new_state.exists() or new_state.is_symlink() or new_private.exists() or new_private.is_symlink() or recovery.exists() or recovery.is_symlink():raise RuntimeError('Project-local destinations already in use')
if old_state.stat().st_dev!=root.stat().st_dev or old_private.stat().st_dev!=root.stat().st_dev:raise RuntimeError('Cross-filesystem rename not allowed')
if old_state.stat().st_uid!=0 or old_private.stat().st_uid!=0 or old_state.stat().st_mode&0o077 or old_private.stat().st_mode&0o077:raise RuntimeError('Unsafe state/vault ownership or mode')
before_files={}
for name in paths:
 p=root/name
 if not p.is_file() or p.is_symlink():raise RuntimeError('Expected runtime file absent: '+name)
 before_files[p]=p.read_bytes()
 if b'/var/lib/telegram-robot-leads' not in before_files[p] and b'/root/project-secrets/telegram-robot-leads' not in before_files[p]:raise RuntimeError('Expected old path missing in '+name)
original_config=before_files[root/'ecosystem.config.js'].decode()
if str(old_state) not in original_config or str(old_private) not in original_config:raise RuntimeError('Runtime config missing old paths')
if not (old_state/'operation-state.json').is_file():raise RuntimeError('Existing operational state missing')
before_sessions=hashes(old_private)
if len(before_sessions)!=2:raise RuntimeError('Two active sessions not found')
items=pm()
bot=details(items,'telegram-robot-leads')
other=details(items,'iptvpn_bot')
if bot['status']!='online' or bot['cwd']!=str(root) or bot['script']!=str(root/'main.py') or other['status']!='online':raise RuntimeError('PM2 baseline changed')
print('BEFORE_BOT_PID='+str(bot['pid']))
print('OTHER_BOT_PID='+str(other['pid']))
print('BEFORE_SESSIONS_COUNT='+str(len(before_sessions)))
stopped=False
moved_state=False
moved_private=False
new_started=False
try:
 fd=os.open(recovery,os.O_WRONLY|os.O_CREAT|os.O_EXCL|os.O_NOFOLLOW,0o600)
 with os.fdopen(fd,'w') as f:
  f.write(original_config)
  f.flush();os.fsync(f.fileno())
 q=cmd(['node','--check',str(recovery)],13)
 if q.returncode:raise RuntimeError('Recovery JS config invalid')
 q=cmd(['pm2','delete','telegram-robot-leads'],35)
 if q.returncode:raise RuntimeError('Could not stop targeted Telegram bot')
 stopped=True
 old_state.rename(new_state)
 moved_state=True
 old_private.rename(new_private)
 moved_private=True
 for p,contents in before_files.items():
  new=contents.replace(str(old_state).encode(),str(new_state).encode())
  new=new.replace(str(old_private).encode(),str(new_private).encode())
  if new==contents:raise RuntimeError('Expected replacement missing in '+p.name)
  p.write_bytes(new)
 for p in before_files:
  if p.suffix=='.py':
   q=cmd([str(root/'.venv/bin/python'),'-m','py_compile',str(p)],15)
   if q.returncode:raise RuntimeError('Python syntax error in '+str(p.relative_to(root)))
 if cmd(['node','--check',str(root/'ecosystem.config.js')],12).returncode:raise RuntimeError('PM2 JS syntax invalid')
 if cmd(['/bin/bash','-n',str(root/'scripts/telegram-robot-leads-status.sh')],12).returncode:raise RuntimeError('Status script Bash syntax invalid')
 verify="import sys;sys.path.insert(0,"+repr(str(root/'scripts'))+");import telethon_sessions as t;t._private_dir(t.DEFAULT_VAULT);assert str(t.DEFAULT_VAULT)=="+repr(str(new_private))
 q=cmd([str(root/'.venv/bin/python'),'-c',verify],19)
 if q.returncode:raise RuntimeError('Offline private vault validation failed')
 if hashes(new_private)!=before_sessions:raise RuntimeError('Session inode/size/hash mismatch after move')
 if not (new_state/'operation-state.json').is_file():raise RuntimeError('State did not move')
 q=cmd(['pm2','start',str(root/'ecosystem.config.js'),'--only','telegram-robot-leads','--update-env'],48)
 if q.returncode:
  print('START_ERROR_CLASS='+q.stderr.strip()[:200])
  raise RuntimeError('New-path Telegram bot start failed')
 new_started=True
 for i in range(4):
  time.sleep(2)
  fresh=pm()
  after=details(fresh,'telegram-robot-leads')
  if after['status']=='online' and after['cwd']==str(root) and after['script']==str(root/'main.py') and after['state']==str(new_state/'operation-state.json') and after['journal']==str(new_state/'supervisor-events.jsonl') and str(new_private) in str(after['args']):break
  print('HEALTH_POLL',i+1,'STATUS',str(after['status']),'CWD_MATCH',str(after['cwd']==str(root)),'STATE_MATCH',str(after['state']==str(new_state/'operation-state.json')),'VAULT_MATCH',str(str(new_private) in str(after['args'])))
 else:raise RuntimeError('New state/vault runtime metadata did not become healthy')
 if details(fresh,'iptvpn_bot')!=other:raise RuntimeError('Unrelated IPTV PN Bot changed')
 if hashes(new_private)!=before_sessions:raise RuntimeError('Sessions changed after new process start')
 if cmd(['pm2','save'],30).returncode:raise RuntimeError('Could not persist reboot configuration')
except Exception as exc:
 print('MIGRATION_FAILURE_CLASS='+str(exc)[:230])
 if stopped:
  present=[x for x in pm() if x.get('name')=='telegram-robot-leads']
  if present:
   q=cmd(['pm2','delete','telegram-robot-leads'],30)
   print('ROLLBACK_STOP_RC='+str(q.returncode))
 for p,blob in before_files.items():
  p.write_bytes(blob)
 if moved_private and new_private.is_dir() and not old_private.exists():new_private.rename(old_private)
 if moved_state and new_state.is_dir() and not old_state.exists():new_state.rename(old_state)
 if stopped:
  q=cmd(['pm2','start',str(recovery),'--only','telegram-robot-leads','--update-env'],45)
  print('ROLLBACK_START_RC='+str(q.returncode))
  if q.returncode==0:
   time.sleep(2)
   b=details(pm(),'telegram-robot-leads')
   print('ROLLBACK_BOT_STATUS='+str(b['status']))
   print('ROLLBACK_BOT_CWD='+str(b['cwd']))
   q=cmd(['pm2','save'],28)
   print('ROLLBACK_SAVE_RC='+str(q.returncode))
 raise
finally:
 if recovery.is_file() and not recovery.is_symlink():recovery.unlink()
print('NEW_CANONICAL_STATE='+str(new_state))
print('NEW_CANONICAL_VAULT='+str(new_private))
print('TWO_SESSIONS_CONTENT_UNCHANGED=YES')
print('STATE_PREVIOUS_PATH_ABSENT='+str(not old_state.exists()))
print('VAULT_PREVIOUS_PATH_ABSENT='+str(not old_private.exists()))
print('PATCHED_PROJECT_FILES='+str(len(before_files)))
print('NEW_BOT_PID='+str(after['pid']))
print('OTHER_BOT_PID_UNCHANGED='+str(other['pid']))
print('PM2_REBOOT_STATE_SAVED=YES')
print('TELEGRAM_PROJECT_STATE_VAULT_CUTOVER=PASS')
